DO $$ BEGIN IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'assessment_results' AND column_name = 'is_absent') THEN UPDATE "assessment_results" SET "result_status" = 'absent' WHERE "is_absent" = true; END IF; END $$; UPDATE "assessment_results" SET "marks_obtained" = 0 WHERE "result_status" = 'absent' AND "marks_obtained" IS NULL; UPDATE "assessment_results" AS result SET "result_status" = 'scored' WHERE result."result_status" = 'not_entered' AND (result."marks_obtained" IS NOT NULL OR EXISTS (SELECT 1 FROM "rubric_scores" AS rubric WHERE rubric."result_id" = result."id")); ALTER TABLE "assessment_results" DROP CONSTRAINT IF EXISTS "chk_assessment_results_absent_has_no_marks"; ALTER TABLE "assessment_results" DROP CONSTRAINT IF EXISTS "assessment_results_absent_means_zero_check"; ALTER TABLE "assessment_results" ADD CONSTRAINT "assessment_results_absent_means_zero_check" CHECK ("result_status" <> 'absent' OR COALESCE("marks_obtained", -1) = 0); ALTER TABLE "assessment_results" DROP COLUMN IF EXISTS "is_absent";
